
# Characteristics of the four-tripotent problem that are generated by systems with at most 4 equations
# (= the scope of Kişi et al. 2021).  new = 3005 - orbits_nz.
include(joinpath(@__DIR__, "common.jl"))
const Q = Rational{Int64}
inp = CharacterizationInput([Q[1,-1,0] for _ in 1:4], Q[1,-1,0])
t = @elapsed r = run_characterization(inp; verbose=false, max_level=4)
nz = count(S -> all(i -> any(s -> !iszero(r.L[s][i]), S), 1:4), keys(r.orbits))
println("closures of systems with ≤4 equations: closed=", length(r.closed), " orbits=", length(r.orbits), " orbits_nz=", nz, " exhaustive=", r.exhaustive, " [", round(t; digits=1), " s]")
